#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Wizard-specific helpers (author section).

# Shell profile that persists BEADS_ACTOR and the GNU tools PATH.
PROFILE="$HOME/.zshrc"; [[ "${SHELL:-}" == */bash ]] && PROFILE="$HOME/.bashrc"

# upsert_profile MARKER LINE: replaces any profile line containing MARKER with LINE.
upsert_profile() {
  local marker="$1" line="$2" tmp
  touch "$PROFILE"
  tmp=$(mktemp)
  grep -vF "$marker" "$PROFILE" > "$tmp" || true
  printf '%s\n' "$line" >> "$tmp"
  cat "$tmp" > "$PROFILE"; rm -f "$tmp"
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$marker" "$PROFILE"
}

have() { command -v "$1" >/dev/null 2>&1; }

# Git Bash / MSYS2 on Windows: tools come from winget, flock is optional, GNU timeout ships with Git Bash.
case "$(uname -s)" in MINGW*|MSYS*|CYGWIN*) WINDOWS=true ;; *) WINDOWS=false ;; esac
gnu_timeout() { local t; for t in timeout gtimeout; do have "$t" && "$t" --version 2>/dev/null | grep -q GNU && return; done; return 1; }
winget_id() {
  case "$1" in
    jq) echo jqlang.jq ;; just) echo Casey.Just ;; gh) echo GitHub.cli ;; awscli) echo Amazon.AWSCLI ;;
  esac
}
# win_path_dirs: put the folders winget and the Beads installer use on PATH for this run (new shells get them from Windows).
win_path_dirs() {
  local d
  for d in "${LOCALAPPDATA:-}/Microsoft/WinGet/Links" "${PROGRAMFILES:-}/GitHub CLI" \
           "${PROGRAMFILES:-}/Amazon/AWSCLIV2" "${LOCALAPPDATA:-}/Programs/bd"; do
    d="$(cygpath -u "$d" 2>/dev/null)" || continue
    [[ -d "$d" && ":$PATH:" != *":$d:"* ]] && PATH="$PATH:$d"
  done
  export PATH
}

# prompt_default VAR "Label" DEFAULT reads a visible value, Enter keeps DEFAULT.
prompt_default() {
  local input=""
  read -e -r -p "  $2 [${3}]: " input || true
  printf -v "$1" '%s' "${input:-$3}"
}

# repo_path URL prints <owner-or-workspace>/<repo> from an HTTPS or SSH git URL.
repo_path() {
  local u="${1%.git}"
  u="${u#https://}"; u="${u#git@}"; u="${u#*@}"; u="${u/://}"
  echo "${u#*/}"
}

aws_ok() { have aws && aws sts get-caller-identity >/dev/null 2>&1; }

run_wizard() {

cd "$(dirname "$0")/.."
TOTAL_STAGES=7

banner "Beads setup (GitHub or Bitbucket remote)"

# ── 1. Host ─────────────────────────────────────────────────────────────────
stage "Repository host"
say "Beads stores its database at refs/dolt/<factory> on this repo's origin."
origin="$(git remote get-url origin 2>/dev/null || true)"
case "$origin" in
  *github.com*)    HOST_DEFAULT=github ;;
  *bitbucket*)     HOST_DEFAULT=bitbucket ;;
  *)               HOST_DEFAULT=github ;;
esac
[[ -n "$origin" ]] && note "current origin: $origin"
while :; do
  prompt_default HOST "Where is the repository hosted? github / bitbucket" "$HOST_DEFAULT"
  [[ "$HOST" == github || "$HOST" == bitbucket ]] && break
  warn "type github or bitbucket"
done
if [[ "$HOST" == github ]]; then
  TOTAL_STAGES=6
  note "GitHub: git authenticates through the GitHub CLI (gh)."
else
  note "Bitbucket: a repository access token in AWS Secrets Manager, read by scripts/git-credential-beads."
fi
pause

# ── 2. Tools ────────────────────────────────────────────────────────────────
stage "Command-line tools"
needs="bd, jq, just, GNU timeout (coreutils)"
$WINDOWS || needs+=", flock"
[[ "$HOST" == github ]] && needs+=", gh" || needs+=", aws"
say "Beads sync needs: $needs."
GNUBIN=""
if have brew; then
  GNUBIN="$(brew --prefix)/opt/coreutils/libexec/gnubin"
  [[ -d "$GNUBIN" ]] && export PATH="$GNUBIN:$PATH"
fi
if $WINDOWS; then win_path_dirs; fi
missing=()
have jq      || missing+=(jq)
have just    || missing+=(just)
$WINDOWS || have flock || missing+=(flock)
if ! gnu_timeout; then
  if $WINDOWS; then
    warn "GNU timeout not found: run this wizard from Git Bash (Git for Windows), not PowerShell or cmd."
    SKIPPED+=("re-run 'just setup-beads' from Git Bash")
  else
    missing+=(coreutils)
  fi
fi
if [[ "$HOST" == github ]]; then have gh || missing+=(gh); else have aws || missing+=(awscli); fi
if (( ${#missing[@]} )); then
  say "Missing: ${missing[*]}"
  if $WINDOWS && have winget && confirm "Install them with winget (${missing[*]})?"; then
    for tool in "${missing[@]}"; do
      winget install --exact --source winget --id "$(winget_id "$tool")" || warn "winget could not install $tool"
    done
    win_path_dirs
  elif have brew && confirm "Install them with: brew install ${missing[*]}?"; then
    brew install "${missing[@]}"
    GNUBIN="$(brew --prefix)/opt/coreutils/libexec/gnubin"
    export PATH="$GNUBIN:$PATH"
  else
    SKIPPED+=("install: ${missing[*]}")
    warn "skipped; install them with your package manager before 'just beads init'"
  fi
else
  note "all present"
fi
if [[ -n "$GNUBIN" && "$(command -v timeout || true)" == "$GNUBIN/timeout" ]]; then
  upsert_profile "coreutils/libexec/gnubin" "export PATH=\"$GNUBIN:\$PATH\"  # GNU timeout for scripts/beads.sh"
fi
if have bd; then
  note "bd: $(bd version 2>/dev/null | head -n1)"
elif confirm "bd is missing. Install it with the official installer (scripts/beads.sh install)?"; then
  scripts/beads.sh install
  if $WINDOWS; then win_path_dirs; fi
else
  SKIPPED+=("install bd: scripts/beads.sh install")
fi
# winget adds its folders to the Windows PATH, but the Beads installer does not: persist it for Git Bash.
if $WINDOWS && [[ -x "$(cygpath -u "${LOCALAPPDATA:-}" 2>/dev/null)/Programs/bd/bd.exe" ]]; then
  upsert_profile "/Programs/bd" "export PATH=\"\$PATH:\$(cygpath -u \"\$LOCALAPPDATA\")/Programs/bd\"  # Beads CLI"
fi
pause

# ── 3. Sign-in ──────────────────────────────────────────────────────────────
if [[ "$HOST" == github ]]; then
  stage "GitHub CLI sign-in"
  say "git reads and writes the Beads ref through gh's credentials."
  if gh auth status --hostname github.com >/dev/null 2>&1; then
    note "already signed in as $(gh api user --jq .login 2>/dev/null || echo '?')"
  else
    step "gh opens a browser: choose GitHub.com, HTTPS, then 'Login with a web browser'."
    gh auth login --hostname github.com --git-protocol https --web
  fi
  gh auth setup-git --hostname github.com && note "git now uses gh for https://github.com"
else
  stage "AWS session"
  say "The credential helper reads the Bitbucket token from AWS Secrets Manager."
  until aws_ok; do
    step "In another terminal, sign in to AWS the way your team does (for example: aws sso login)."
    note "This shell needs the same AWS_PROFILE / credentials; export them before running the wizard."
    confirm "Signed in? Check again" || { SKIPPED+=("AWS sign-in"); warn "skipped"; break; }
  done
  aws_ok && note "AWS identity: $(aws sts get-caller-identity --query Arn --output text)"
fi
pause

# ── 4. Identity ─────────────────────────────────────────────────────────────
stage "Your identity"
say "Beads records who claims and closes each ticket."
prompt_default GIT_NAME  "Git author name"  "$(git config --global user.name || true)"
prompt_default GIT_EMAIL "Git author email" "$(git config --global user.email || true)"
[[ -n "$GIT_NAME" ]]  && git config --global user.name "$GIT_NAME"
[[ -n "$GIT_EMAIL" ]] && git config --global user.email "$GIT_EMAIL"
actor_default="${BEADS_ACTOR:-}"
[[ -z "$actor_default" && "$HOST" == github ]] && actor_default="$(gh api user --jq .login 2>/dev/null || true)"
prompt_default BEADS_ACTOR "Beads handle (BEADS_ACTOR)" "$actor_default"
if [[ -n "$BEADS_ACTOR" ]]; then
  export BEADS_ACTOR
  upsert_profile "export BEADS_ACTOR=" "export BEADS_ACTOR=\"$BEADS_ACTOR\""
else
  SKIPPED+=("set BEADS_ACTOR in $PROFILE")
fi
pause

# ── 5. Repository ───────────────────────────────────────────────────────────
stage "Repository (origin)"
origin="$(git remote get-url origin 2>/dev/null || true)"
if [[ "$HOST" == github ]]; then
  if [[ "$origin" == https://github.com/* ]]; then
    note "origin: $origin"
  elif [[ "$origin" == git@github.com:* ]]; then
    if confirm "origin uses SSH; switch it to https://github.com/$(repo_path "$origin").git?"; then
      git remote set-url origin "https://github.com/$(repo_path "$origin").git"
    else
      SKIPPED+=("set an HTTPS GitHub origin")
    fi
  elif [[ -n "$origin" ]]; then
    warn "origin is $origin, not GitHub. Fix it, then re-run this wizard."
    SKIPPED+=("point origin at an HTTPS GitHub URL")
  else
    slug=""
    prompt_default slug "Repository (owner/name)" "$(gh api user --jq .login 2>/dev/null || echo owner)/$(basename "$PWD")"
    if gh repo view "$slug" >/dev/null 2>&1; then
      note "$slug exists on GitHub"
    elif confirm "Create private repo $slug on GitHub (no push)?"; then
      gh repo create "$slug" --private
    fi
    if gh repo view "$slug" >/dev/null 2>&1; then
      git remote add origin "https://github.com/$slug.git"
    else
      SKIPPED+=("create the GitHub repo and add it as origin")
    fi
  fi
else
  if [[ "$origin" == https://*bitbucket* ]]; then
    note "origin: $origin"
  elif [[ "$origin" == git@*bitbucket* ]]; then
    bb_host="${origin#git@}"; bb_host="${bb_host%%:*}"
    if confirm "origin uses SSH; switch it to https://$bb_host/$(repo_path "$origin").git?"; then
      git remote set-url origin "https://$bb_host/$(repo_path "$origin").git"
    else
      SKIPPED+=("set an HTTPS Bitbucket origin")
    fi
  elif [[ -n "$origin" ]]; then
    warn "origin is $origin, not Bitbucket. Fix it, then re-run this wizard."
    SKIPPED+=("point origin at an HTTPS Bitbucket URL")
  else
    say "Create the repository in Bitbucket if it does not exist yet (leave it empty)."
    open_url "https://bitbucket.org/repo/create"
    step "Copy its HTTPS clone URL: https://bitbucket.org/<workspace>/<repo>.git"
    ask BB_URL "Paste the HTTPS clone URL:"
    BB_URL="${BB_URL#git clone }"
    if [[ "$BB_URL" == https://*bitbucket*/*/* ]]; then
      git remote add origin "$BB_URL"
    else
      SKIPPED+=("add an HTTPS Bitbucket origin")
      warn "that is not an HTTPS Bitbucket URL; skipped"
    fi
  fi
fi
prompt_default FACTORY "Factory name (database ref refs/dolt/<factory>)" \
  "$(git config --local beads.factory || basename "$PWD")"
git config --local beads.factory "$FACTORY"
note "origin: $(git remote get-url origin 2>/dev/null || echo '<none>')"
pause

# ── 6. Bitbucket token (Bitbucket only) ─────────────────────────────────────
if [[ "$HOST" == bitbucket ]]; then
  stage "Bitbucket access token → AWS Secrets Manager"
  if ! SECRET_PATH="$(scripts/beads.sh secret-path 2>/dev/null)"; then
    warn "origin is not set up yet, so there is no secret path. Fix stage 5 and re-run."
    SKIPPED+=("store the Bitbucket token in AWS")
  elif ! aws_ok; then
    warn "no AWS session; sign in and re-run this wizard."
    SKIPPED+=("store the Bitbucket token at $SECRET_PATH")
  else
    note "secret path: $SECRET_PATH"
    if aws secretsmanager get-secret-value --secret-id "$SECRET_PATH" --query SecretString --output text 2>/dev/null \
        | jq -e '.token | select(. != "")' >/dev/null 2>&1 \
        && ! confirm "A token is already stored there. Replace it?"; then
      note "keeping the stored token"
    else
      origin="$(git remote get-url origin)"
      bb_host="${origin#https://}"; bb_host="${bb_host#*@}"; bb_host="${bb_host%%/*}"
      open_url "https://$bb_host/$(repo_path "$origin")/admin/access-tokens"
      step "Repository settings → Security → Access tokens → Create Repository Access Token."
      step "Name it 'beads', tick Repositories: Read and Write, then Create."
      step "Copy the token (Bitbucket shows it once)."
      ask_secret BB_TOKEN "Paste the token (hidden):"
      if [[ -z "$BB_TOKEN" ]]; then
        SKIPPED+=("store the Bitbucket token at $SECRET_PATH")
      elif confirm "Store it at $SECRET_PATH in AWS Secrets Manager?"; then
        secret_file="$(mktemp)"; chmod 600 "$secret_file"
        printf '%s' "$BB_TOKEN" | jq -Rs '{username: "x-token-auth", token: .}' > "$secret_file"
        if aws secretsmanager describe-secret --secret-id "$SECRET_PATH" >/dev/null 2>&1; then
          aws secretsmanager put-secret-value --secret-id "$SECRET_PATH" --secret-string "file://$secret_file" >/dev/null
        else
          aws secretsmanager create-secret --name "$SECRET_PATH" --secret-string "file://$secret_file" \
            --description "Bitbucket repository access token for the Beads Dolt remote" >/dev/null
        fi
        rm -f "$secret_file"
        printf '  %s✓ stored%s token at %s\n' "$GREEN" "$RESET" "$SECRET_PATH"
      else
        SKIPPED+=("store the Bitbucket token at $SECRET_PATH")
      fi
      unset BB_TOKEN
    fi
  fi
  pause
fi

# ── 7. Initialise ───────────────────────────────────────────────────────────
stage "Initialise the Beads database"
if [[ -e .beads/metadata.json ]] && scripts/beads.sh doctor 2>/dev/null | grep -q '^probe: *ok'; then
  note "Beads is already initialised and synced here."
  if confirm "Show 'just beads doctor'?"; then scripts/beads.sh doctor || true; fi
elif [[ -e .beads/config.yaml ]] && grep -q 'remote:' .beads/config.yaml && [[ ! -e .beads/metadata.json ]]; then
  say "This repo already has a shared Beads remote; joining it."
  scripts/beads.sh join && scripts/beads.sh doctor || SKIPPED+=("just beads join")
else
  if [[ -z "$(git ls-remote --heads origin 2>/dev/null || true)" ]]; then
    branch="$(git branch --show-current)"
    say "origin has no branches yet, and Beads cannot push to an empty repository."
    if confirm "Push '$branch' to origin now (publishes the repo's commits)?"; then
      git push -u origin "$branch"
    else
      SKIPPED+=("git push -u origin $branch, then just beads init")
    fi
  fi
  say "Issue IDs look like <prefix>-a1b2."
  prompt_default PREFIX "Issue prefix" "$(basename "$PWD" | cut -c1-3 | tr '[:upper:]' '[:lower:]')"
  if confirm "Run scripts/beads.sh init $PREFIX now (creates .beads/, may commit, pushes the ref)?"; then
    scripts/beads.sh init "$PREFIX" && scripts/beads.sh doctor || SKIPPED+=("just beads init $PREFIX (see the error above)")
    say "Review with 'git show --stat HEAD', then commit .beads/config.yaml."
  else
    SKIPPED+=("just beads init $PREFIX")
  fi
fi
pause

finish
note "Open a new terminal (or: source $PROFILE) so BEADS_ACTOR and PATH apply."
}

run_wizard "$@"; exit
